1	// fix_decision.go は、立案の結果 (plans[].decision) の検査と、生成サマリへの描画を持つ。
2	// キーの意味の SSOT は skills/review-triage/references/record-schema.md の「立案の結果」、
3	// 選択肢の意味の SSOT は skills/review-triage-fix/references/fix-decision.md。
4	package main
5	
6	import "fmt"
7	
8	// recordDecision は plans[].decision を表す。修正の内容は approach に書くので、ここには持たない。
9	type recordDecision struct {
10		Target          string `yaml:"target"`
11		Baseline        string `yaml:"baseline"`
12		BaselineFixed   bool   `yaml:"baseline_fixed"`
13		Choice          string `yaml:"choice"`
14		ChoiceReason    string `yaml:"choice_reason"`
15		DocChange       string `yaml:"doc_change"`
16		DocChangeReason string `yaml:"doc_change_reason"`
17	}
18	
19	// recordDecisionFirstRun は、記録の中で最初に decision を書いた回の添字を返す。無ければ -1。
20	// この回と、それより後の回では、pending の問題に decision を必須にする。決め方と理由は
21	// recordPriorDefectFirstRun と同じ (過去の記録を書き換えさせずに通すため)。
22	func recordDecisionFirstRun(runs []recordRun) int {
23		for ri, run := range runs {
24			for _, pl := range run.Plans {
25				if pl.Decision != nil {
26					return ri
27				}
28			}
29		}
30		return -1
31	}
32	
33	// recordDecisionProblems は問題 1 つの decision を検査する。required が偽の回
34	// (recordDecisionFirstRun の回より前の回) では、pending に無くても報告しない。done と
35	// done-external には、どの回でも求めない。理由は record-schema.md の「立案の結果」。
36	func recordDecisionProblems(required bool, pl recordPlan) []string {
37		var problems []string
38		add := func(format string, args ...any) {
39			problems = append(problems, fmt.Sprintf(format, args...))
40		}
41		d := pl.Decision
42		if d == nil {
43			switch pl.Status {
44			case "not-fixed":
45				add("status not-fixed には decision が必須 (choice: undecided と、直さない理由を書く)")
46			case "pending":
47				if required {
48					add("decision がありません (立案の結果を書く。この記録では、この回かそれより前の回で decision を書いている)")
49				}
50			}
51			return problems
52		}
53		if pl.Status == "investigated" {
54			add("調査済み (investigated) では decision を書かない。修正方法を決めたのなら status: pending にする")
55			return problems
56		}
57		for _, kv := range []struct{ key, val string }{
58			{"target", d.Target}, {"baseline", d.Baseline}, {"choice_reason", d.ChoiceReason},
59		} {
60			if kv.val == "" {
61				add("decision.%s がありません", kv.key)
62			}
63		}
64		switch d.Choice {
65		case "baseline", "target", "neither", "undecided":
66		default:
67			add("decision.choice は baseline / target / neither / undecided のいずれか: %q", d.Choice)
68		}
69		if d.BaselineFixed && (d.Choice == "target" || d.Choice == "neither") {
70			add("decision.baseline_fixed が true なのに、decision.choice が %s です (基準が変えられないなら、基準を直す選択肢は候補にならない)", d.Choice)
71		}
72		if d.Choice == "undecided" {
73			if pl.Status != "not-fixed" && pl.Status != "awaiting-human" {
74				add("decision.choice が undecided なのに、status が %s です (今回は直さないなら not-fixed、人間の回答を待つなら awaiting-human)", pl.Status)
75			}
76			if d.DocChange != "" {
77				add("decision.choice が undecided なのに、decision.doc_change があります (直さないので、修正の内容は無い)")
78			}
79		}
80		if pl.Status == "not-fixed" && d.Choice != "undecided" {
81			add("status not-fixed なのに、decision.choice が undecided ではありません: %q", d.Choice)
82		}
83		switch d.DocChange {
84		case "rewrite", "add":
85			if d.DocChangeReason == "" {
86				add("decision.doc_change が %s なのに、decision.doc_change_reason がありません (前の順のもので済まない理由を書く)", d.DocChange)
87			}
88		case "remove", "":
89			if d.DocChangeReason != "" {
90				add("decision.doc_change_reason は、decision.doc_change が rewrite か add のときだけ書く (doc_change %q)", d.DocChange)
91			}
92		default:
93			add("decision.doc_change は remove / rewrite / add のいずれか: %q", d.DocChange)
94		}
95		return problems
96	}
97	
98	// renderDecision は立案の結果を 1 行にする。自由文字列はすべて recordCell を通す。
99	func renderDecision(d *recordDecision) string {
100		s := "箇所: " + recordCell(d.Target) + " / 基準: " + recordCell(d.Baseline)
101		if d.BaselineFixed {
102			s += " (変えられない)"
103		}
104		s += " / 選択: " + recordChoiceJa(d.Choice) + " / 理由: " + recordCell(d.ChoiceReason)
105		if d.DocChange != "" {
106			s += " / 文書の修正: " + recordDocChangeJa(d.DocChange)
107		}
108		if d.DocChangeReason != "" {
109			s += " (" + recordCell(d.DocChangeReason) + ")"
110		}
111		return s
112	}
113	
114	func recordChoiceJa(s string) string {
115		switch s {
116		case "baseline":
117			return "基準の内容を正とする"
118		case "target":
119			return "指摘された箇所の内容を正とする"
120		case "neither":
121			return "どちらも正としない"
122		case "undecided":
123			return "決めない"
124		}
125		return recordCell(s)
126	}
127	
128	func recordDocChangeJa(s string) string {
129		switch s {
130		case "remove":
131			return "消す"
132		case "rewrite":
133			return "書き換える"
134		case "add":
135			return "足す"
136		}
137		return recordCell(s)
138	}
