		noSHAYet()
	default:
		add("%s: status は investigated / pending / awaiting-human / done / done-external / not-fixed のいずれか: %q", pn, pl.Status)
	}
	for _, m := range recordDecisionProblems(decisionFirstRun >= 0 && ri >= decisionFirstRun, pl) {
